// Badge: Pricing capsule label with accent edge light
import { Group, Mesh, Shape, ShapeGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, color, mix, smoothstep, float, min, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- capsule geometry ---
  const width = 1.2;
  const height = 0.5;
  const radius = height / 2;

  const shape = new Shape();
  // start at leftmost point of left semicircle
  shape.moveTo(-width / 2, 0);
  // left semicircle (counterclockwise from leftmost to top)
  shape.absarc(-width / 2 + radius, 0, radius, Math.PI, Math.PI / 2, false);
  // top edge
  shape.lineTo(width / 2 - radius, -height / 2);
  // right semicircle (clockwise from top to bottom)
  shape.absarc(width / 2 - radius, 0, radius, Math.PI / 2, -Math.PI / 2, true);
  // bottom edge
  shape.lineTo(-width / 2 + radius, height / 2);
  // left semicircle (clockwise from bottom to leftmost) – closes the shape
  shape.absarc(-width / 2 + radius, 0, radius, -Math.PI / 2, Math.PI, true);
  shape.closePath();

  const geometry = new ShapeGeometry(shape);

  // --- material (initial placeholder, texture updates later) ---
  const material = new MeshBasicNodeMaterial();
  material.colorNode = color(0xffffff); // placeholder
  material.needsUpdate = true;

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- load texture and build custom shader ---
  let textureDisposable = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      textureDisposable = tex;
      const texNode = texture(tex);
      const uvNode = uv();
      // distance to nearest edge (in UV space)
      const distX = min(uvNode.x, float(1).sub(uvNode.x));
      const distY = min(uvNode.y, float(1).sub(uvNode.y));
      const dist = min(distX, distY);
      // edge glow mask: 1 near edge, 0 away
      const edgeMask = float(1).sub(smoothstep(float(0.0), float(0.05), dist));
      const accentColorNode = color(config.colors.accent || '#ff2a38');
      const texColor = texNode;
      const finalColor = mix(texColor, accentColorNode, edgeMask.mul(float(0.5)));
      material.colorNode = finalColor;
      material.needsUpdate = true;
    });
  }

  // --- interactions ---
  let hoverTween = null;
  let clickTween = null;

  group.userData.handlers = {
    hover: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: '+=0.15',
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    unhover: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: '-=0.15',
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    click: () => {
      ctx.emit('hub-pricing.select');
      // press-down effect
      if (clickTween) clickTween.kill();
      clickTween = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            duration: 0.3,
            ease: 'power4.out',
          });
        },
      });
    },
  };

  // --- cleanup ---
  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (clickTween) clickTween.kill();
    geometry.dispose();
    material.dispose();
    if (textureDisposable) textureDisposable.dispose();
  };

  return group;
}
